import type { Item } from "../types";
import { itemScore } from "../scorer";
import { next, shuffle } from "../rng";

export type BlindState = {
  players: string[];
  size: number;
  queue: string[];
  weights: Record<string, number>;
  ranks: Record<string, (string | null)[]>; // rank index 0 = best
  turn: number; // turn % players = who places; floor(turn / players) = which reveal
  done: boolean;
  seed: number;
};

export function init(o: { players: string[]; poolIds: string[]; size: number; weights: Record<string, number>; seed: number }): BlindState {
  const [queue, seed] = shuffle(o.poolIds, o.seed);
  return {
    players: o.players,
    size: o.size,
    queue: queue.slice(0, o.size),
    weights: o.weights,
    ranks: Object.fromEntries(o.players.map((p) => [p, Array(o.size).fill(null)])),
    turn: 0,
    done: false,
    seed,
  };
}

export const revealIndex = (s: BlindState) => Math.floor(s.turn / s.players.length);
export const turnPlayer = (s: BlindState) => s.players[s.turn % s.players.length]!;
export const currentItemId = (s: BlindState) => (s.done ? null : s.queue[revealIndex(s)]!);

export function place(s: BlindState, rank: number): BlindState {
  if (s.done || rank < 0 || rank >= s.size) return s;
  const p = turnPlayer(s);
  if (s.ranks[p]![rank] != null) return s;
  const row = [...s.ranks[p]!];
  row[rank] = currentItemId(s)!;
  const turn = s.turn + 1;
  return { ...s, ranks: { ...s.ranks, [p]: row }, turn, done: turn >= s.players.length * s.size };
}

export const freeRanks = (s: BlindState, p: string) => s.ranks[p]!.map((v, i) => (v == null ? i : -1)).filter((i) => i >= 0);

/** True order, best first, by the mission metric. */
export function trueOrder(items: Item[], weights: Record<string, number>): string[] {
  return [...items].sort((a, b) => itemScore(b, weights) - itemScore(a, weights)).map((i) => i.id);
}

/** 0-100: 100 = identical to the true order (normalised footrule distance). */
export function accuracy(order: (string | null)[], truth: string[]): number {
  const n = truth.length;
  if (!n) return 0;
  const tpos = new Map(truth.map((id, i) => [id, i]));
  let d = 0;
  order.forEach((id, i) => {
    d += id == null ? n : Math.abs((tpos.get(id) ?? n) - i);
  });
  const max = Math.floor((n * n) / 2) || 1;
  return Math.round(Math.max(0, 1 - d / max) * 1000) / 10;
}

/** AI placement: estimate the item's percentile with noise, then take the closest free rank. */
export function aiPlace(s: BlindState, item: Item, noise = 14): { rank: number; seed: number } {
  const [r, seed] = next(s.seed);
  const p = turnPlayer(s);
  const est = Math.min(100, Math.max(0, itemScore(item, s.weights) + (r - 0.5) * 2 * noise));
  const ideal = (1 - est / 100) * (s.size - 1);
  const free = freeRanks(s, p);
  const rank = free.reduce((best, i) => (Math.abs(i - ideal) < Math.abs(best - ideal) ? i : best), free[0]!);
  return { rank, seed };
}
